// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Wallet c;

    function setUp() public {
        c = new Wallet();
    }

    function _run(address target, uint256 amount) internal {
        vm.assume(true);
        uint256 balBefore = address(target).balance;
        bool reverted;
        try c.withdraw(amount) { reverted = false; } catch { reverted = true; }
        uint256 balAfter = address(target).balance;
        assertTrue(!(!reverted && balAfter != balBefore + amount));
    }

    function testFuzz_run(address target, uint256 amount) public {
        _run(target, amount);
    }

    receive() external payable {}
}
